// @param float scale 2 0 8
// @param float thinness 0.8 0 3.2
// @param float mode 0 0 1
// @param color colorA 1 0 0
// @param color colorB 0 1 0
// @param color colorC 0 0 1
// @param color background 0 0 0
// @param float seed 0 0 100
material.colorNode = TEXTURES.neonLights({ scale: params.scale, thinness: params.thinness, mode: params.mode, colorA: params.colorA, colorB: params.colorB, colorC: params.colorC, background: params.background, seed: params.seed });

// @param float amountCm 6.0 0.0 20.0
// @param float frequency 0.12 0.0 1.0
// @param float speed 1.5 0.0 6.0
// max.js FeatureTest: TSL vertex displacement (positionNode, cm) along the local normal, animated.
const p = TSL.positionLocal;
const wave = TSL.sin(p.x.mul(params.frequency).add(TSL.time.mul(params.speed)))
    .mul(TSL.sin(p.y.mul(params.frequency).sub(TSL.time.mul(params.speed.mul(0.7)))));
material.positionNode = p.add(TSL.normalLocal.mul(wave.mul(params.amountCm)));
material.colorNode = TSL.vec3(0.95, 0.55, 0.2).mul(wave.mul(0.35).add(0.75));
material.roughnessNode = TSL.float(0.4);

mat.mapTSL:
// @param float scale 2.5 0 10
// @param float rings 4.5 0 18
// @param float lengths 1 0 4
// @param float angle 0 -6.2832 6.2832
// @param float fibers 0.3 0 1.2
// @param float fibersDensity 10 -5 5
// @param color color 0.8 0.4 0
// @param color background 0.4 0.1 0
// @param float seed 0 0 100
return TEXTURES.wood({ scale: params.scale, rings: params.rings, lengths: params.lengths, angle: params.angle, fibers: params.fibers, fibersDensity: params.fibersDensity, color: params.color, background: params.background, seed: params.seed });

mat.tslCode:
// @param float speed 1.0 0.0 4.0
// @param float stripes 24.0 2.0 80.0
// @param color tint 0.25 0.85 1.0
// max.js FeatureTest: map1 sampling, @param uniforms, Max vertex colours (channel 0), animated emissive.
const vc = TSL.maxVertexColor(0).rgb;
const base = TSL.texture(maps.map1).rgb;
const band = TSL.sin(TSL.uv().y.mul(params.stripes).add(TSL.time.mul(params.speed))).mul(0.5).add(0.5);
material.colorNode = base.mul(vc).mul(band.mul(0.6).add(0.4));
material.emissiveNode = params.tint.mul(band.pow(12.0)).mul(1.5);
material.roughnessNode = TSL.float(0.35);
material.metalnessNode = TSL.float(0.0);
